function refreshPack() { const p = G.pack; R.packMesh.visible = !!p; if (p) { const h = heightAt(p.x, p.z); R.packMesh.position.set(p.x, h, p.z); R.packPoi.x = p.x; R.packPoi.y = h + 0.5; R.packPoi.z = p.z; } }
